import { NotteClient } from "notte-sdk";

const notte = new NotteClient();
// the simple way: create a session that gets stopped automatically
await notte.Session().use(async (session) => {
  await session.execute({
    type: "goto",
    url: "https://www.google.com",
  });
});

// for more control, start it manually
const session = notte.Session();
await session.start();

import { NotteClient } from "notte-sdk";
import { readFileSync } from "fs";

const notte = new NotteClient();
// load the cookies from json and inject them in the session
const cookies = JSON.parse(readFileSync("cookies.json", "utf-8"));

await notte.Session().use(async (session) => {
  await session.setCookies(cookies);
});

import { NotteClient } from "notte-sdk";
import { writeFileSync } from "fs";

const notte = new NotteClient();
await notte.Session().use(async (session) => {
  // perform some operation that creates cookies
  // ...
  // then save the cookies to json
  const cookies = await session.getCookies();
  writeFileSync("cookies.json", JSON.stringify(cookies));
});

import { NotteClient } from "notte-sdk";

const notte = new NotteClient();
await notte.Session().use(async (session) => {
  // Observe the state of a webpage
  await session.execute({
    type: "goto",
    url: "https://google.com/travel/flights",
  });
  const obs = await session.observe();
  console.log("Page Title:", obs.metadata.title);
  console.log(
    "Available Actions:\n",
    obs.space.description
  );
  // Example Output:
  // Flight Search
  // * I1: Enter departure location
  // ...
});

import { NotteClient } from "notte-sdk";

const notte = new NotteClient();
await notte.Session().use(async (session) => {
  // go to duckduckgo
  await session.execute({
    type: "goto",
    url: "https://www.duckduckgo.com",
  });

  // fill the search bar with our query
  await session.execute({
    type: "fill",
    value: "dog pictures",
    selector: 'internal:role=combobox[name="Search with DuckDuckGo"i]',
  });
});

import { NotteClient } from "notte-sdk";
import { z } from "zod";

const StoryInfo = z.object({
  title: z.string(),
  points: z.number().nullable(),
});

const Stories = z.object({
  stories: z.array(StoryInfo),
});

const notte = new NotteClient();
await notte.Session().use(async (session) => {
  await session.execute({
    type: "goto",
    url: "https://news.ycombinator.com",
  });
  const stories = await session.scrape({
    instructions:
      "Extract the top 5 story titles and their points",
    response_format: Stories,
  });
});

import { NotteClient } from "notte-sdk";

const notte = new NotteClient();
const task = "find a cute dog on google images";

await notte.Session().use(async (session) => {
  const agent = notte.Agent({ session, max_steps: 5 });
  // this runs the agent and waits for completion
  const response = await agent.run({ task });
  console.log(`success=${response.success}, answer=${response.answer}`);
});

import { NotteClient } from "notte-sdk";

const notte = new NotteClient();

await notte.Session().use(async (session) => {
  const agent = notte.Agent({ session });
  await agent.start({
    task: "find a cute dog on google images",
  });

  // stops without waiting for the agent to finish
  await agent.stop();
});

